#!/usr/bin/env python3
import os
OUT=os.path.join(os.path.dirname(os.path.abspath(__file__)),'features/plans')
P='../../../photos/'
CSS='''
html,body{margin:0;background:#000}
.phone{position:relative;width:393px;height:852px;overflow:hidden;background:#050506;color:#f5f1ea;font-family:-apple-system,Inter,sans-serif}
.sb{position:absolute;top:18px;left:30px;right:30px;display:flex;justify-content:space-between;font:600 15px Inter,sans-serif;z-index:6}
.top{position:absolute;top:56px;left:16px;right:16px;display:flex;align-items:center;justify-content:space-between;height:40px;z-index:5}
.c{width:40px;height:40px;border-radius:50%;background:rgba(40,40,46,.7);border:1px solid rgba(255,255,255,.12);display:flex;align-items:center;justify-content:center}
.c svg{width:19px;height:19px;stroke:#fff;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.ttl{font:800 30px "Barlow Condensed",sans-serif;text-transform:uppercase;letter-spacing:.3px}
.h1{font:800 34px/1 "Barlow Condensed",sans-serif;text-transform:uppercase}
.cap{font:700 11px Inter;letter-spacing:1.6px;text-transform:uppercase;color:rgba(245,241,234,.45)}
.sub{font:500 13.5px -apple-system,Inter;color:rgba(245,241,234,.64)}
.amb{color:#ffb547}
.tabs{position:absolute;left:16px;right:16px;bottom:20px;height:68px;border-radius:34px;background:rgba(28,28,32,.92);border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:space-around;z-index:9;font:600 11px Inter,sans-serif;color:#cfcac0}
.tabs span{display:flex;flex-direction:column;align-items:center;gap:4px}.tabs .on{color:#fff}
.tabs i{width:22px;height:20px;border-radius:5px;background:#cfcac0;display:block}.tabs .on i{background:#fff}
.pill{display:inline-flex;align-items:center;height:24px;padding:0 10px;border-radius:12px;font:700 10.5px Inter;letter-spacing:1.3px;text-transform:uppercase}
.pill.a{background:#ffb547;color:#050506}.pill.g{background:#1d1d22;color:rgba(245,241,234,.7)}
.row{display:flex;align-items:center;gap:12px;background:#121215;border-radius:16px;padding:12px 14px}
.tile{width:44px;height:44px;border-radius:11px;display:flex;align-items:center;justify-content:center;font:800 17px "Barlow Condensed";color:#fff}
.btn{height:50px;border-radius:14px;display:flex;align-items:center;justify-content:center;font:800 17px "Barlow Condensed";letter-spacing:1px;text-transform:uppercase}
.btn.w{background:#fff;color:#050506}.btn.o{border:1.5px solid rgba(255,255,255,.25);color:#fff}
.ph{background-size:cover;background-position:center}
.chev{width:11px;height:11px;stroke:#8a867e;fill:none;stroke-width:2.6;stroke-linecap:round}
.dash{border:1.5px dashed rgba(255,255,255,.28)}
'''
I={'back':'<path d="M15 5l-7 7 7 7"/>','x':'<path d="M6 6l12 12M18 6L6 18"/>','plus':'<path d="M12 5v14M5 12h14"/>','more':'<circle cx="5.5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="18.5" cy="12" r="1.5"/>','cal':'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M4 10h16M9 3v4M15 3v4"/>','bell':'<path d="M6 16V11a6 6 0 0 1 12 0v5l1.5 2h-15zM10 21h4"/>','ticket':'<path d="M3 9a2 2 0 0 0 0 6v3h18v-3a2 2 0 0 1 0-6V6H3z"/>','sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>','pin':'<path d="M12 21s7-6.2 7-11a7 7 0 0 0-14 0c0 4.8 7 11 7 11z"/><circle cx="12" cy="10" r="2.5"/>','search':'<circle cx="11" cy="11" r="6.5"/><path d="M16 16l4 4"/>','check':'<path d="M5 12.5l4.5 4.5L19 7.5"/>'}
def ic(n,st='',cls=''): return f'<svg viewBox="0 0 24 24" class="{cls}" style="fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;width:18px;height:18px;{st}">{I[n]}</svg>'
def tile(code,col,fg='#fff'): return f'<div class="tile" style="background:{col};color:{fg}">{code}</div>'
def page(title,body,tabs=True,sel=0):
    t='<div class="tabs"><span class="%s"><i></i>Timeline</span><span class="%s"><i style="border-radius:50%%"></i>Map</span><span class="%s"><i></i>Passport</span><span class="%s"><i style="border-radius:50%%"></i>You</span></div>'%tuple('on' if i==sel else '' for i in range(4)) if tabs else ''
    return f'<!doctype html><html><head><meta charset="utf-8"><title>{title}</title><link rel="stylesheet" href="../../../kit/kit.css"><style>{CSS}</style></head><body><div class="phone"><div class="sb"><span>9:41</span><span>●●● 100</span></div>{body}{t}</div><script>window.__ready=true</script></body></html>'
def w(n,t,b,**k): open(f'{OUT}/{n}.html','w').write(page(t,b,**k))
def nav(title,right='x',left='back'): return f'<div class="top"><div class="c">{ic(left)}</div><div class="ttl" style="font-size:20px">{title}</div><div class="c">{ic(right)}</div></div>'

# 1 team-first: pick team -> upcoming home games
games=[('SAT','JUN 20','vs Cardinals','7:15 PM','78°',"CHC","#2f6bff"),('SUN','JUN 21','vs Cardinals','1:20 PM','81°',"CHC","#2f6bff"),('TUE','JUN 30','vs Brewers','7:40 PM','74°',"CHC","#2f6bff"),('FRI','JUL 03','vs Pirates','2:20 PM','83°',"CHC","#2f6bff"),('SAT','JUL 04','vs Pirates','1:20 PM','85°',"CHC","#2f6bff")]
rows=''.join(f'<div class="row" style="margin-bottom:8px"><div style="width:46px;text-align:center"><div class="cap">{d}</div><div style="font:800 24px Barlow Condensed">{dd.split()[1]}</div><div class="cap" style="font-size:9px">{dd.split()[0]}</div></div><div style="flex:1"><div style="font:800 18px Barlow Condensed;text-transform:uppercase">{o}</div><div class="sub" style="font-size:12.5px">{t} · {wx}</div></div><div class="pill {"a" if i==0 else "g"}">{"Planned" if i==0 else "Plan it"}</div></div>' for i,(d,dd,o,t,wx,c,col) in enumerate(games))
b=nav('Plan a game')+f'<div style="position:absolute;top:116px;left:16px;right:16px"><div style="display:flex;gap:8px;margin-bottom:16px"><span class="pill a" style="height:32px;padding:0 14px">By team</span><span class="pill g" style="height:32px;padding:0 14px">By stadium</span></div><div class="row" style="margin-bottom:18px">{tile("CHC","#2f6bff")}<div style="flex:1"><div style="font:800 20px Barlow Condensed;text-transform:uppercase">Chicago</div><div class="sub" style="font-size:12.5px">Wrigley Field · you\'ve been 11 times</div></div>{ic("search","color:#8a867e")}</div><div class="cap" style="margin-bottom:10px">Upcoming home games</div>{rows}</div>'
w('v1-plan-by-team','Plan A · pick a team, then a game',b,tabs=False)

# 2 stadium/date first
b=nav('Plan a visit')+f'''<div style="position:absolute;top:116px;left:16px;right:16px"><div style="display:flex;gap:8px;margin-bottom:16px"><span class="pill g" style="height:32px;padding:0 14px">By team</span><span class="pill a" style="height:32px;padding:0 14px">By stadium</span></div>
<div class="row" style="margin-bottom:10px"><div class="ph" style="width:44px;height:44px;border-radius:50%;background-image:url({P}fenway-day.jpg);box-shadow:0 0 0 2px #FF5A4F"></div><div style="flex:1"><div style="font:800 20px Barlow Condensed;text-transform:uppercase">Fenway Park</div><div class="sub" style="font-size:12.5px">Boston · never been</div></div>{ic("pin","color:#8a867e")}</div>
<div class="row" style="margin-bottom:18px">{ic("cal","color:#ffb547;width:22px;height:22px")}<div style="flex:1;font:700 17px Inter">Aug 14 – 17, 2026</div><span class="sub">4 days</span></div>
<div class="cap" style="margin-bottom:10px">Games there in that window</div>
<div class="row" style="margin-bottom:8px"><div style="width:46px;text-align:center"><div style="font:800 24px Barlow Condensed">14</div><div class="cap" style="font-size:9px">FRI</div></div><div style="flex:1"><div style="font:800 18px Barlow Condensed">YANKEES AT RED SOX</div><div class="sub" style="font-size:12.5px">7:10 PM · rivalry</div></div><div style="width:22px;height:22px;border-radius:50%;border:2px solid rgba(255,255,255,.3)"></div></div>
<div class="row" style="margin-bottom:8px;box-shadow:inset 0 0 0 1.5px #ffb547"><div style="width:46px;text-align:center"><div style="font:800 24px Barlow Condensed">15</div><div class="cap" style="font-size:9px">SAT</div></div><div style="flex:1"><div style="font:800 18px Barlow Condensed">YANKEES AT RED SOX</div><div class="sub" style="font-size:12.5px">4:05 PM · rivalry</div></div><div style="width:22px;height:22px;border-radius:50%;background:#ffb547;color:#000;display:flex;align-items:center;justify-content:center">{ic("check","width:14px;height:14px;stroke-width:3")}</div></div>
<div class="row" style="margin-bottom:8px"><div style="width:46px;text-align:center"><div style="font:800 24px Barlow Condensed">16</div><div class="cap" style="font-size:9px">SUN</div></div><div style="flex:1"><div style="font:800 18px Barlow Condensed">YANKEES AT RED SOX</div><div class="sub" style="font-size:12.5px">1:35 PM</div></div><div style="width:22px;height:22px;border-radius:50%;border:2px solid rgba(255,255,255,.3)"></div></div>
<div class="row dash" style="background:transparent;margin-bottom:16px"><span class="sub">Not going to a game? Plan a stadium tour</span></div>
<div class="btn w">Add to my plans</div></div>'''
w('v2-plan-by-stadium','Plan B · pick a stadium and dates',b,tabs=False)

# 3 timeline with Upcoming section
def card(ph,t1,t2,d1,d2,up=False):
    return f'<div style="display:flex;border-radius:18px;overflow:hidden;background:#121215;margin-bottom:12px;height:112px"><div class="ph" style="width:132px;background-image:url({P}{ph}.jpg);position:relative"><div style="position:absolute;left:8px;top:8px;background:rgba(5,5,6,.75);border-radius:8px;padding:4px 8px;text-align:center"><div style="font:800 20px/1 Barlow Condensed">{d1}</div><div class="cap" style="font-size:9px">{d2}</div></div></div><div style="flex:1;padding:12px 14px;display:flex;flex-direction:column;justify-content:center"><div style="font:800 20px/1 Barlow Condensed;text-transform:uppercase">{t1}</div><div class="sub" style="margin-top:4px;font-size:12.5px">{t2}</div></div></div>'
b=f'<div class="top"><div class="ttl">Timeline</div><div style="display:flex;gap:10px"><div class="c">{ic("plus")}</div></div></div><div style="position:absolute;top:112px;left:16px;right:16px"><div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px"><span class="cap amb">Upcoming · 2</span><span class="sub" style="font-size:12px">See plans</span></div>'
b+=f'<div class="ph" style="height:128px;border-radius:18px;background-image:url({P}fenway-night.jpg);position:relative;margin-bottom:10px;overflow:hidden"><div style="position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,5,6,.92),rgba(5,5,6,.25))"></div><div style="position:absolute;left:16px;top:14px"><span class="pill a">In 12 days</span><div style="font:800 26px/1 Barlow Condensed;margin-top:10px">YANKEES AT RED SOX</div><div class="sub" style="margin-top:6px;font-size:12.5px">Fenway Park · Sat, Aug 15 · 4:05 PM</div></div></div>'
b+=f'<div style="display:flex;gap:10px;margin-bottom:18px"><div class="row dash" style="flex:1;background:transparent"><div><div style="font:800 17px Barlow Condensed">LIONS AT PACKERS</div><div class="sub" style="font-size:12px">Lambeau · Nov 2</div></div></div></div><div class="cap" style="margin-bottom:10px">Past</div>'
b+=card('wrigley-night','Toronto 8 · New York 5','Rogers Centre','12','JUN')+card('lambeau-concourse','Green Bay at Chicago','Soldier Field','14','DEC')
b+='</div>'
w('v3-timeline-upcoming-section','Timeline A · Upcoming above the past',b)

# 4 timeline: one next-up banner + dashed ghost cards inline chronological
b=f'<div class="top"><div class="ttl">Timeline</div><div style="display:flex;gap:10px"><div class="c">{ic("plus")}</div></div></div><div style="position:absolute;top:112px;left:16px;right:16px">'
b+=f'<div style="display:flex;align-items:center;gap:12px;background:linear-gradient(90deg,#2a1d08,#121215);border:1px solid rgba(255,181,71,.35);border-radius:16px;padding:12px 14px;margin-bottom:14px"><div style="font:800 34px/1 Barlow Condensed;color:#ffb547">12</div><div style="flex:1"><div class="cap amb" style="font-size:10px">Days to go</div><div style="font:800 17px Barlow Condensed;text-transform:uppercase">Yankees at Red Sox · Fenway</div></div>{ic("bell","color:#ffb547")}</div>'
b+=f'<div class="dash" style="border-radius:18px;height:112px;margin-bottom:12px;display:flex;overflow:hidden;opacity:.95"><div class="ph" style="width:132px;background-image:url({P}fenway-day.jpg);filter:grayscale(1) brightness(.6)"></div><div style="padding:12px 14px;display:flex;flex-direction:column;justify-content:center"><span class="pill a" style="width:max-content;margin-bottom:8px">Planned · Aug 15</span><div style="font:800 20px/1 Barlow Condensed">YANKEES AT RED SOX</div><div class="sub" style="font-size:12.5px;margin-top:4px">Fenway Park · 4:05 PM</div></div></div>'
b+=card('wrigley-night','Toronto 8 · New York 5','Rogers Centre','12','JUN')+card('lambeau-concourse','Green Bay at Chicago','Soldier Field','14','DEC')+'</div>'
w('v4-timeline-inline-ghost','Timeline B · planned cards inline, dashed',b)

# 5 upcoming game page
b=f'<div style="position:absolute;left:0;right:0;top:0;height:330px;background:url({P}fenway-night.jpg) center/cover"><div style="position:absolute;inset:0;background:linear-gradient(180deg,rgba(5,5,6,.7),rgba(5,5,6,0) 30%),linear-gradient(0deg,#050506 0,rgba(5,5,6,.6) 40%,rgba(5,5,6,0) 75%)"></div></div><div class="top"><div class="c">{ic("back")}</div><div style="display:flex;gap:10px"><div class="c">{ic("cal")}</div><div class="c">{ic("more")}</div></div></div>'
b+='<div style="position:absolute;left:20px;right:20px;top:178px"><span class="pill a">Planned</span><div style="display:flex;align-items:flex-end;gap:10px;margin:10px 0 6px"><div style="font:800 96px/.8 Barlow Condensed;letter-spacing:-2px">12</div><div style="font:800 22px/1 Barlow Condensed;text-transform:uppercase;padding-bottom:4px">Days<br>to go</div></div><div class="h1" style="font-size:32px">Yankees<br>at Red Sox</div><div class="sub" style="margin-top:8px"><span class="amb">Fenway Park</span>, Sat, Aug 15 · 4:05 PM</div></div>'
rowx=lambda i,t,s,r='':f'<div class="row" style="margin-bottom:8px"><span class="amb">{ic(i,"width:22px;height:22px")}</span><div style="flex:1"><div style="font:700 15px Inter">{t}</div><div class="sub" style="font-size:12.5px">{s}</div></div>{r}</div>'
b+='<div style="position:absolute;left:16px;right:16px;top:384px">'+rowx('sun','Forecast','Partly cloudy · 79° · 10% rain')+rowx('ticket','Tickets & seat','Section 24, Row 8 · added from email','<span class="pill g">Edit</span>')+rowx('bell','Game-day reminder','Notify me at noon on Aug 15','<span style="width:42px;height:26px;border-radius:13px;background:#ffb547;position:relative"><i style="position:absolute;right:3px;top:3px;width:20px;height:20px;border-radius:50%;background:#fff"></i></span>')+rowx('cal','Add to Calendar','Saves it to your calendar')+'<div style="height:6px"></div><div class="btn w">I\'m at the game</div></div>'
w('v5-upcoming-page','Upcoming game page',b,tabs=False)

# 6 game day -> converts
b=f'<div style="position:absolute;left:0;right:0;top:0;height:852px;background:url({P}fenway-night.jpg) center/cover;filter:brightness(.35)"></div>'
b+=f'<div style="position:absolute;left:16px;right:16px;top:120px;background:rgba(28,28,32,.96);border-radius:22px;padding:16px;border:1px solid rgba(255,255,255,.12)"><div style="display:flex;gap:10px;align-items:center"><div style="width:38px;height:38px;border-radius:9px;background:#ffb547;display:flex;align-items:center;justify-content:center;color:#000">{ic("pin")}</div><div><div class="cap" style="font-size:10px">Witness · now</div><div style="font:700 15px Inter">You\'re at Fenway Park</div></div></div><div class="sub" style="margin:10px 0 14px">Yankees at Red Sox, 4:05 PM. Want to save today\'s photos to this game?</div><div style="display:flex;gap:10px"><div class="btn w" style="flex:1;height:44px">Yes, I\'m here</div><div class="btn o" style="flex:1;height:44px">Not today</div></div></div>'
b+=f'<div style="position:absolute;left:16px;right:16px;top:370px"><div class="cap" style="margin-bottom:10px">After you confirm</div><div class="row" style="margin-bottom:8px"><span class="pill a">Planned</span><div style="flex:1;text-align:center;color:#8a867e">&rarr;</div><span class="pill" style="background:#fff;color:#000">Attended</span></div><div class="sub">The plan becomes a normal game: the schedule fills in the score, the photos you take today attach to it automatically, and the stamp lands in your Passport.</div></div>'
w('v6-game-day','Game day · plan becomes a memory',b,tabs=False)

# 7 passport / map: to visit
def st(code,col,date,ghost=False,planned=None):
    if ghost: return f'<div style="height:74px;border-radius:14px;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.14);padding:11px 13px;display:flex;flex-direction:column;justify-content:space-between"><b style="font:800 26px/.9 Barlow Condensed;color:rgba(255,255,255,.3)">{code}</b></div>'
    if planned: return f'<div class="dash" style="height:74px;border-radius:14px;padding:11px 13px;display:flex;flex-direction:column;justify-content:space-between;background:rgba(255,181,71,.08);border-color:#ffb547"><b style="font:800 26px/.9 Barlow Condensed;color:#ffb547">{code}</b><span style="font:700 12px Barlow Condensed;letter-spacing:1.2px;color:#ffb547">{planned}</span></div>'
    return f'<div style="height:74px;border-radius:14px;background:{col};padding:11px 13px;display:flex;flex-direction:column;justify-content:space-between"><b style="font:800 26px/.9 Barlow Condensed">{code}</b><span style="font:700 12px Barlow Condensed;letter-spacing:1.2px;opacity:.85">{date}</span></div>'
cells=[st('CHC','#2f6bff','JUN 14, 2014'),st('CWS','#4a4f58','AUG 22, 2015'),st('STL','#c41e3a','APR 18, 2016'),st('DET','#0c2c56','JUL 9, 2016'),st('BOS','','',planned='AUG 15 · PLANNED'),st('CLE','#e31937','MAY 27, 2017'),st('NYY','#1c2c5b','JUL 20, 2019'),st('ATL','','',ghost=True),st('AZ','','',ghost=True)]
b=f'<div class="top"><div class="ttl">Passport</div><div class="c">{ic("plus")}</div></div><div style="position:absolute;top:112px;left:16px;right:16px"><div style="display:flex;gap:8px;margin-bottom:22px"><span class="pill" style="background:#fff;color:#000;height:34px">MLB</span><span class="pill g" style="height:34px">NFL</span><span class="pill g" style="height:34px">NBA</span><span class="pill g" style="height:34px">NHL</span></div><div style="display:flex;align-items:flex-end;gap:12px;margin-bottom:6px"><div style="font:800 110px/.8 Barlow Condensed;letter-spacing:-3px">7</div><div style="font:800 32px/1 Barlow Condensed;text-transform:uppercase;padding-bottom:6px">of 30<br>MLB parks</div></div><div class="sub amb" style="margin-bottom:16px">+ Fenway Park planned for Aug 15</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">'+''.join(cells)+'</div></div>'
w('v7-passport-planned','Passport · planned stamp',b,sel=2)
